concord::api! {
    pub client Tasks {
        base "https://tasks.example.com/api/tasks";
        read Json;                                  // this API answers in JSON

        GET list(done?: bool) -> Vec<Task> {
            query { done; }
        }

        POST create(task: NewTask) -> Task {
            body json(task);
        }

        GET get(id: u64) -> Task { path "{id}"; }

        DELETE delete(id: u64) { path "{id}"; }
    }
}

pub client Riot(key: Secret) {
    headers { "x-riot-token" = key; }                  // who you are, on every request below
    read Json;                                         // how this API answers
    problem RiotProblem;                               // how this API says no

    scope matches(route: MatchRoute) {
        base "https://{route}.api.riotgames.com";      // every request below
        path "lol/match/v5/matches";

        GET ids(puuid: Puuid, count?: u32) -> Vec<MatchId> {
            path "by-puuid/{puuid}/ids";
            query { count; }
        }

        GET get(id: MatchId) -> Match { path "{id}"; }
    }
}

/// `None` when there is no such player.
GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
    path "by-riot-id/{game_name}/{tag_line}";
    status { 404 => None }
}

GET ids(puuid: Puuid, start?: u32, count?: u32) -> Vec<MatchId> {
    path "by-puuid/{puuid}/ids";
    query { start; count; }
    paginate offset_limit(start, count);
}

pub client Stripe(key: Secret) {
    // base, headers, read …

    part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate cursor(starting_after, List::next_cursor);
    }

    scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
    }

    scope invoices {
        path "v1/invoices";
        GET list(..page) -> List<Invoice>;
    }
}

/// Is it there?
HEAD exists(id: DocId) -> bool {
    path "{id}";
    status { 2xx => true, 404 => false }
}

/// The new document, and where it lives.
POST create(doc: NewDoc) -> Created {
    body json(doc);
    status {
        201 { body, headers } => Created { doc: body, at: headers.require("location")?.to_owned() },
    }
}

/// Plain text, not JSON.
GET readme(repo: String) -> String {
    path "{repo}/readme";
    read Text;
}

/// A diff: `override` replaces a header that is set above.
GET diff() -> Bytes {
    headers { override "accept" = "application/vnd.github.diff"; }
    read Binary;
}

/// A large file, as it comes.
GET download(id: FileId) -> concord::ByteStream {
    path "files/{id}";
    read Stream;                       // `use concord::read::Stream;`
}

/// An upload, on another host.
PUT upload(name: String, file: concord::Body) {
    base "https://uploads.example.com";
    path "files/{name}";
    body file;
}

/// A body made of several inputs (`serde_json`'s `json!`). A `None` is written as `null`.
POST search(text: String, cursor?: String) -> Page {
    path "search";
    body json(json!({ "query": text, "cursor": cursor }));
}

pub client Vault(key: Secret) {
    middleware Signed::new(key.clone());      // every request is signed as it leaves
    // base, read, endpoints …
}

concord::api! {
    /// The Riot Games API (League of Legends subset).
    pub client Riot(
        /// The API key. Sent on every request unless an endpoint removes it.
        key: Secret,
    ) {
        headers { "x-riot-token" = key; }
        read Json;
        problem RiotProblem;

        /// Accounts (regional routing).
        scope account(route: AccountRoute) {
            base "https://{route}.api.riotgames.com";
            path "riot/account/v1/accounts";

            /// The account behind a Riot ID (`name#tag`). `None` when there is no such player.
            GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
                path "by-riot-id/{game_name}/{tag_line}";
                status { 404 => None }
            }

            /// The account of a signed-in player.
            /// Uses the player's own token instead of the API key.
            GET me(access_token: Secret) -> Account {
                path "me";
                headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
            }
        }

        /// Matches (regional routing).
        scope matches(route: MatchRoute) {
            base "https://{route}.api.riotgames.com";
            path "lol/match/v5/matches";

            /// Match ids of a player, newest first.
            GET ids(
                puuid: Puuid,
                start?: u32,
                count?: u32,
                queue?: i32,
                start_time?: i64,
            ) -> Vec<MatchId> {
                path "by-puuid/{puuid}/ids";
                query { start; count; queue; "startTime" = start_time; }
                paginate offset_limit(start, count);
            }

            /// One match.
            GET get(id: MatchId) -> Match { path "{id}"; }
        }
    }
}

pub client Stripe(key: Secret) {
    headers { "authorization" = "Bearer {key}"; }
    read Json;
    problem StripeProblem;

    part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate cursor(starting_after, List::next_cursor);
    }
    part keyed(idempotency_key: String) {
        headers { "idempotency-key" = idempotency_key; }
        idempotent;
    }

    scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
        POST create(customer: NewCustomer, ..keyed) -> Customer { body form(customer); }
    }
}

pub client Vault(key: Secret) {
    base "https://api.vault.example";
    read Json;
    middleware Signed::new(key.clone());        // every request is signed as it leaves

    GET balance() -> Balance { path "balance"; }
}

GET readme(owner: String, repo: String) -> String {
    path "repos/{owner}/{repo}/readme";
    headers { override "accept" = "application/vnd.github.raw+json"; }
    read Text;
}

POST create(request: ChatRequest) -> ChatReply {
    body json(request);
    read ChatRead(request.stream);          // your reader: `Json` or `Stream`, by this flag
}

GET pdf(id: InvoiceId) -> concord::ByteStream {
    path "invoices/{id}/pdf";
    read Stream;
}

/// `None` when there is no such player.
GET by_riot_id(game_name: String, tag_line: String) -> Option<Account> {
    path "by-riot-id/{game_name}/{tag_line}";
    status { 404 => None }
}

/// Not changed since `etag`: `None`.
GET get_if_changed(id: DocId, etag?: String) -> Option<Doc> {
    path "{id}";
    headers { "if-none-match" = etag; }
    status { 304 => None }
}

/// A document with its version, for the `If-Match` of the next call.
GET get(id: DocId) -> Versioned<Doc> {
    path "{id}";
    status { 200 { body, headers } => Versioned { etag: headers.get("etag").map(String::from), value: body } }
}

/// Is it there?
HEAD exists(id: DocId) -> bool {
    path "{id}";
    status { 2xx => true, 404 => false }
}

POST create(task: NewTask) -> Created {
    body json(task);
    status { 201 { body, headers } => created(body, headers)? }
}

POST charge(new: NewCharge) -> Result<Charge, Declined> {
    path "charges";
    body form(new);
    status { 200 { body } => Ok(body), 402 { body } => Err(body) }
}

pub client Vault(key: Secret) {
    base "https://api.vault.example";
    read Json;
    middleware Signed::new(key.clone());        // every request is signed as it leaves

    GET balance() -> Balance { path "balance"; }
}

POST create(new: NewCustomer, idempotency_key: String) -> Customer {
    body form(new);
    headers { "idempotency-key" = idempotency_key; }
    idempotent;                    // this API promises: the same key, the same result
}

POST charge(new: NewCharge, key?: String) -> Charge {
    body form(new);
    headers { "idempotency-key" = key; }
    idempotent key.is_some();      // safe to repeat only when the caller gave a key
}

GET list(limit?: u32, starting_after?: String) -> List<Customer> {
    query { limit; starting_after; }
    paginate move |call, page| page.value().next_cursor().map(|cursor| call.starting_after(cursor));
}

part page(limit?: u32, starting_after?: String) {
        query { limit; starting_after; }
        paginate cursor(starting_after, List::next_cursor);
    }

scope customers {
        path "v1/customers";
        GET list(email?: String, ..page) -> List<Customer> { query { email; } }
    }

concord::api! {
    /// League of Legends, Riot accounts, and Teamfight Tactics.
    /// Retry is opt-in; use crate::retry(). For shared 429 pauses use crate::with_cooldown().
    pub client Riot(key: Secret) {
        headers { "x-riot-token" = key; }
        read Json;
        problem RiotProblem;

        /// Regional services. Choose the player's match cluster explicitly.
        /// For account-v1 use Americas, Asia or Europe; support for Sea is (unsure).
        scope regional(route: Region) {
            base "https://{route}.api.riotgames.com";

            /// account-v1. A regional route is not the player's platform shard.
            scope account {
                path "riot/account/v1";
                /// None means no account; it does not establish whether a route was correct.
                GET by_puuid(puuid: Puuid) -> Option<Account> {
                    path "accounts/by-puuid/{puuid}";
                    status { 404 => None }
                }
                GET by_riot_id(game_name: GameName, tag_line: TagLine) -> Option<Account> {
                    path "accounts/by-riot-id/{game_name}/{tag_line}";
                    status { 404 => None }
                }
                /// RSO token obtained by the application; no API key is sent here.
                GET me(access_token: Secret) -> Account {
                    path "accounts/me";
                    headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
                }
                /// Primarily other Riot games; usable game values for LoL/TFT are (unsure).
                GET active_shard(game: Game, puuid: Puuid) -> Option<ActiveShard> {
                    path "active-shards/by-game/{game}/by-puuid/{puuid}";
                    status { 404 => None }
                }
                /// game is lol or tft. Returned region-to-Platform mapping is (unsure).
                GET active_region(game: Game, puuid: Puuid) -> Option<AccountRegion> {
                    path "region/by-game/{game}/by-puuid/{puuid}";
                    status { 404 => None }
                }
            }

            /// match-v5, including the event timeline.
            scope matches {
                path "lol/match/v5/matches";
                /// Newest first. Times are Unix seconds; count is 0..=100 (unsure: zero).
                /// Omitted start/count use server defaults. Paging is not a stable snapshot.
                GET ids(puuid: Puuid, start?: u32, count?: u32,
                    queue?: i32, match_type?: MatchType,
                    start_time?: i64, end_time?: i64) -> Vec<MatchId> {
                    path "by-puuid/{puuid}/ids";
                    query { start; count; queue; "type" = match_type;
                        "startTime" = start_time; "endTime" = end_time; }
                    paginate offset_limit(start, count);
                }
                /// None for an unavailable match, including data outside retention.
                GET get(id: MatchId) -> Option<Match> {
                    path "{id}";
                    status { 200 { body: game } => Some(game), 404 => None }
                }
                /// A complete JSON timeline; the 64 MiB cap is this crate's choice.
                GET timeline(id: MatchId) -> Option<MatchTimeline> {
                    path "{id}/timeline";
                    read Json.limit(64 * concord::MIB);
                    status { 404 => None }
                }
                /// (unsure) Newer replay listing: response schema, filters and availability.
                GET replays(puuid: Puuid) -> PlayerReplays {
                    path "by-puuid/{puuid}/replays";
                }
            }

            /// tft-match-v1. TFT match IDs are distinct from LoL match IDs.
            scope tft_matches {
                path "tft/match/v1/matches";
                /// count max 100; start/end time support is (unsure). Times: Unix seconds.
                GET ids(puuid: Puuid, start?: u32, count?: u32,
                    start_time?: i64, end_time?: i64) -> Vec<TftMatchId> {
                    path "by-puuid/{puuid}/ids";
                    query { start; count; "startTime" = start_time; "endTime" = end_time; }
                    paginate offset_limit(start, count);
                }
                GET get(id: TftMatchId) -> Option<TftMatch> {
                    path "{id}";
                    status { 404 => None }
                }
            }

            /// lol-rso-match-v1: (unsure) exact operations, paths and filters.
            /// Token acquisition/refresh belongs to the application, not this scope.
            scope rso_matches(access_token: Secret) {
                path "lol/rso-match/v1/matches";
                headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
                GET ids(puuid: Puuid, start?: u32, count?: u32) -> Vec<MatchId> {
                    path "by-puuid/{puuid}/ids";
                    query { start; count; }
                    // No automatic pager: the termination contract is (unsure).
                }
                GET get(id: MatchId) -> Option<Match> {
                    path "{id}";
                    status { 404 => None }
                }
            }

            /// tournament-v5. Requires a tournament-enabled key; routing is (unsure).
            scope tournaments {
                path "lol/tournament/v5";
                /// Creates codes, not a paged read. count is at most 1000 (unsure).
                POST create_codes(tournament_id: TournamentId, parameters: CodeParameters,
                    count?: u32) -> Vec<TournamentCode> {
                    path "codes";
                    query { "tournamentId" = tournament_id; count; }
                    body concord::json(parameters);
                }
                GET code(code: TournamentCode) -> Option<CodeDetails> {
                    path "codes/{code}";
                    status { 404 => None }
                }
                PUT update_code(code: TournamentCode, parameters: CodeUpdate) {
                    path "codes/{code}";
                    body concord::json(parameters);
                }
                GET lobby_events(code: TournamentCode) -> LobbyEvents {
                    path "lobby-events/by-code/{code}";
                }
                /// (unsure) v5 game result collection and response schema.
                GET games(code: TournamentCode) -> Vec<TournamentGame> {
                    path "games/by-code/{code}";
                }
                POST register_provider(parameters: ProviderRegistration) -> ProviderId {
                    path "providers";
                    body concord::json(parameters);
                }
                POST create(parameters: TournamentRegistration) -> TournamentId {
                    path "tournaments";
                    body concord::json(parameters);
                }
            }

            /// tournament-stub-v5. Stub results do not establish that a real lobby exists.
            scope tournament_stub {
                path "lol/tournament-stub/v5";
                POST create_codes(tournament_id: TournamentId, parameters: CodeParameters,
                    count?: u32) -> Vec<TournamentCode> {
                    path "codes";
                    query { "tournamentId" = tournament_id; count; }
                    body concord::json(parameters);
                }
                GET code(code: TournamentCode) -> Option<CodeDetails> {
                    path "codes/{code}";
                    status { 404 => None }
                }
                GET lobby_events(code: TournamentCode) -> LobbyEvents {
                    path "lobby-events/by-code/{code}";
                }
                POST register_provider(parameters: ProviderRegistration) -> ProviderId {
                    path "providers";
                    body concord::json(parameters);
                }
                POST create(parameters: TournamentRegistration) -> TournamentId {
                    path "tournaments";
                    body concord::json(parameters);
                }
            }
        }

        /// Platform services. Euw1 is a platform; Europe is a regional cluster.
        scope platform(route: Platform) {
            base "https://{route}.api.riotgames.com";

            /// champion-v3: the current free champion rotation, including new-player rules.
            GET champion_rotations() -> ChampionRotations { path "lol/platform/v3/champion-rotations"; }
            /// lol-status-v4: maintenance and incidents for this platform.
            GET status() -> PlatformStatus { path "lol/status/v4/platform-data"; }
            /// tft-status-v1.
            GET tft_status() -> PlatformStatus { path "tft/status/v1/platform-data"; }
            /// third-party-code-v4: legacy verification code; availability is (unsure).
            #[deprecated(note = "Legacy summoner-ID verification; availability (unsure)")]
            GET third_party_code(summoner_id: SummonerId) -> Option<String> {
                path "lol/platform/v4/third-party-code/by-summoner/{summoner_id}";
                status { 404 => None }
            }

            /// champion-mastery-v4. Top lists have a count, not a next page.
            scope mastery {
                path "lol/champion-mastery/v4";
                GET by_puuid(puuid: Puuid) -> Vec<ChampionMastery> {
                    path "champion-masteries/by-puuid/{puuid}";
                }
                GET by_champion(puuid: Puuid, champion_id: ChampionId) -> Option<ChampionMastery> {
                    path "champion-masteries/by-puuid/{puuid}/by-champion/{champion_id}";
                    status { 404 => None }
                }
                GET top(puuid: Puuid, count?: u32) -> Vec<ChampionMastery> {
                    path "champion-masteries/by-puuid/{puuid}/top";
                    query { count; }
                }
                GET score(puuid: Puuid) -> i32 { path "scores/by-puuid/{puuid}"; }
                /// Legacy summoner-ID variants below: continued availability is (unsure).
                #[deprecated(note = "Use by_puuid; legacy availability (unsure)")]
                GET by_summoner(summoner_id: SummonerId) -> Vec<ChampionMastery> {
                    path "champion-masteries/by-summoner/{summoner_id}";
                }
                #[deprecated(note = "Use by_champion; legacy availability (unsure)")]
                GET champion_by_summoner(summoner_id: SummonerId, champion_id: ChampionId) -> Option<ChampionMastery> {
                    path "champion-masteries/by-summoner/{summoner_id}/by-champion/{champion_id}";
                    status { 404 => None }
                }
                #[deprecated(note = "Use top; legacy availability (unsure)")]
                GET top_by_summoner(summoner_id: SummonerId, count?: u32) -> Vec<ChampionMastery> {
                    path "champion-masteries/by-summoner/{summoner_id}/top";
                    query { count; }
                }
                #[deprecated(note = "Use score; legacy availability (unsure)")]
                GET score_by_summoner(summoner_id: SummonerId) -> i32 { path "scores/by-summoner/{summoner_id}"; }
            }

            /// clash-v1.
            scope clash {
                path "lol/clash/v1";
                /// (unsure) PUUID successor to players/by-summoner.
                GET players(puuid: Puuid) -> Vec<ClashPlayer> { path "players/by-puuid/{puuid}"; }
                /// Legacy route; current availability is (unsure).
                GET players_by_summoner(summoner_id: SummonerId) -> Vec<ClashPlayer> {
                    path "players/by-summoner/{summoner_id}";
                }
                GET team(team_id: ClashTeamId) -> Option<ClashTeam> {
                    path "teams/{team_id}";
                    status { 404 => None }
                }
                GET tournaments() -> Vec<ClashTournament> { path "tournaments"; }
                GET tournament_by_team(team_id: ClashTeamId) -> Option<ClashTournament> {
                    path "tournaments/by-team/{team_id}";
                    status { 404 => None }
                }
                GET tournament(tournament_id: ClashTournamentId) -> Option<ClashTournament> {
                    path "tournaments/{tournament_id}";
                    status { 404 => None }
                }
            }

            /// league-v4. Queue/tier/division use Riot's uppercase wire names.
            scope league {
                path "lol/league/v4";
                GET challenger(queue: Queue) -> LeagueList { path "challengerleagues/by-queue/{queue}"; }
                GET grandmaster(queue: Queue) -> LeagueList { path "grandmasterleagues/by-queue/{queue}"; }
                GET master(queue: Queue) -> LeagueList { path "masterleagues/by-queue/{queue}"; }
                GET get(league_id: LeagueId) -> Option<LeagueList> {
                    path "leagues/{league_id}";
                    status { 404 => None }
                }
                /// Empty when unranked; a 404 remains an error rather than an empty ranking.
                GET by_puuid(puuid: Puuid) -> Vec<LeagueEntry> { path "entries/by-puuid/{puuid}"; }
                /// Legacy summoner-ID route; availability is (unsure).
                GET by_summoner(summoner_id: SummonerId) -> Vec<LeagueEntry> { path "entries/by-summoner/{summoner_id}"; }
                /// Page starts at 1. Empty page ends iteration; a short page does not.
                GET entries(queue: Queue, tier: Tier, division: Division, page?: u32) -> Vec<LeagueEntry> {
                    path "entries/{queue}/{tier}/{division}";
                    query { page; }
                    paginate crate::league_pages!();
                }
            }
            /// league-exp-v4: also covers apex tiers (accepted division there is (unsure)).
            scope league_exp {
                path "lol/league-exp/v4";
                GET entries(queue: Queue, tier: Tier, division: Division, page?: u32) -> Vec<LeagueEntry> {
                    path "entries/{queue}/{tier}/{division}";
                    query { page; }
                    paginate crate::league_pages!();
                }
            }

            /// lol-challenges-v1. Percentiles are keyed JSON objects, not pages.
            scope challenges {
                path "lol/challenges/v1";
                GET configurations() -> Vec<ChallengeConfig> { path "challenges/config"; }
                GET percentiles() -> ChallengePercentiles { path "challenges/percentiles"; }
                GET configuration(challenge_id: ChallengeId) -> Option<ChallengeConfig> {
                    path "challenges/{challenge_id}/config";
                    status { 404 => None }
                }
                /// Top players at level; limit has no offset/cursor companion.
                GET leaders(challenge_id: ChallengeId, level: ChallengeLevel, limit?: u32) -> Vec<ChallengeLeader> {
                    path "challenges/{challenge_id}/leaderboards/by-level/{level}";
                    query { limit; }
                }
                GET challenge_percentiles(challenge_id: ChallengeId) -> LevelPercentiles {
                    path "challenges/{challenge_id}/percentiles";
                }
                GET player(puuid: Puuid) -> Option<PlayerChallenges> {
                    path "player-data/{puuid}";
                    status { 404 => None }
                }
            }

            /// spectator-v5. The path says by-summoner, but the input is a PUUID.
            scope spectator {
                path "lol/spectator/v5";
                /// None means no currently observable game, not a nonexistent account.
                GET current_game(puuid: Puuid) -> Option<CurrentGame> {
                    path "active-games/by-summoner/{puuid}";
                    status { 404 => None }
                }
                /// (unsure) Continued availability in v5.
                GET featured_games() -> FeaturedGames { path "featured-games"; }
            }
            /// spectator-tft-v5 is a TFT family despite its /lol URL prefix.
            scope tft_spectator {
                path "lol/spectator/tft/v5";
                GET current_game(puuid: Puuid) -> Option<TftCurrentGame> {
                    path "active-games/by-puuid/{puuid}";
                    status { 404 => None }
                }
            }

            /// summoner-v4. Use Riot account lookup for player-facing names.
            scope summoner {
                path "lol/summoner/v4/summoners";
                GET by_puuid(puuid: Puuid) -> Option<Summoner> {
                    path "by-puuid/{puuid}";
                    status { 404 => None }
                }
                GET me(access_token: Secret) -> Summoner {
                    path "me";
                    headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
                }
                /// Legacy identifiers below; current availability is (unsure).
                #[deprecated(note = "Use by_puuid; legacy availability (unsure)")]
                GET by_id(summoner_id: SummonerId) -> Option<Summoner> {
                    path "{summoner_id}";
                    status { 404 => None }
                }
                #[deprecated(note = "Use by_puuid; legacy availability (unsure)")]
                GET by_account(account_id: EncryptedAccountId) -> Option<Summoner> {
                    path "by-account/{account_id}";
                    status { 404 => None }
                }
                #[deprecated(note = "Use account.by_riot_id; availability (unsure)")]
                GET by_name(name: String) -> Option<Summoner> {
                    path "by-name/{name}";
                    status { 404 => None }
                }
            }

            /// tft-league-v1. TFT queue names differ from LoL queue names.
            scope tft_league {
                path "tft/league/v1";
                GET challenger(queue?: TftQueue) -> TftLeagueList {
                    path "challenger"; query { queue; }
                }
                GET grandmaster(queue?: TftQueue) -> TftLeagueList {
                    path "grandmaster"; query { queue; }
                }
                GET master(queue?: TftQueue) -> TftLeagueList {
                    path "master"; query { queue; }
                }
                /// (unsure) Continued availability of lookup by league ID.
                GET get(league_id: LeagueId) -> Option<TftLeagueList> {
                    path "leagues/{league_id}";
                    status { 404 => None }
                }
                GET by_puuid(puuid: Puuid) -> Vec<TftLeagueEntry> { path "by-puuid/{puuid}"; }
                /// Legacy summoner-ID route; availability is (unsure).
                GET by_summoner(summoner_id: SummonerId) -> Vec<TftLeagueEntry> { path "entries/by-summoner/{summoner_id}"; }
                GET entries(tier: Tier, division: Division, queue?: TftQueue, page?: u32) -> Vec<TftLeagueEntry> {
                    path "entries/{tier}/{division}";
                    query { queue; page; }
                    paginate crate::league_pages!();
                }
                /// e.g. RANKED_TFT_TURBO; this top ladder is not paged.
                GET top_rated(queue: TftQueue) -> Vec<TftTopRated> { path "rated-ladders/{queue}/top"; }
            }

            /// tft-summoner-v1. me uses RSO; the other calls use the API key.
            scope tft_summoner {
                path "tft/summoner/v1/summoners";
                GET by_puuid(puuid: Puuid) -> Option<TftSummoner> {
                    path "by-puuid/{puuid}";
                    status { 404 => None }
                }
                GET me(access_token: Secret) -> TftSummoner {
                    path "me";
                    headers { remove "x-riot-token"; "authorization" = "Bearer {access_token}"; }
                }
                /// Legacy identifiers below; current availability is (unsure).
                #[deprecated(note = "Use by_puuid; legacy availability (unsure)")]
                GET by_id(summoner_id: SummonerId) -> Option<TftSummoner> {
                    path "{summoner_id}";
                    status { 404 => None }
                }
                #[deprecated(note = "Use by_puuid; legacy availability (unsure)")]
                GET by_account(account_id: EncryptedAccountId) -> Option<TftSummoner> {
                    path "by-account/{account_id}";
                    status { 404 => None }
                }
                #[deprecated(note = "Use account.by_riot_id; availability (unsure)")]
                GET by_name(name: String) -> Option<TftSummoner> {
                    path "by-name/{name}";
                    status { 404 => None }
                }
            }
        }
    }
}

concord::api! {
    /// Stripe API v1. Every POST requires a durable, operation-specific key.
    pub client Stripe(
        key: Secret,
        /// Choose a version matching this crate's response models.
        version: String,
        /// Connect account; omitted for requests on the platform account.
        account?: AccountId,
    ) {
        base "https://api.stripe.com";
        headers {
            "authorization" = "Bearer {key}";
            "Stripe-Version" = version;
            "Stripe-Account" = account;
        }
        read Json;
        problem StripeProblem;

        scope customers {
            path "v1/customers";

            POST create(new: NewCustomer, key: IdempotencyKey, expand?: Vec<String>) -> Customer {
                headers { "Idempotency-Key" = key; }
                body stripe_form(new, expand);
                idempotent;
            }
            /// A deleted customer can be a tombstone; a 404 remains an error.
            GET get(id: CustomerId, expand?: Vec<String>) -> CustomerRecord {
                path "{id}";
                query { "expand[]" = expand; }
            }
            POST update(id: CustomerId, changes: UpdateCustomer, key: IdempotencyKey, expand?: Vec<String>) -> Customer {
                path "{id}";
                headers { "Idempotency-Key" = key; }
                body stripe_form(changes, expand);
                idempotent;
            }
            DELETE delete(id: CustomerId) -> Deleted<CustomerId> { path "{id}"; }
            GET list(email?: String, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: CustomerId, expand?: Vec<String>) -> List<Customer> {
                query { email; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
            /// Search is eventually consistent; do not use it to verify a write.
            GET search(query: String, page?: String, limit?: u32, expand?: Vec<String>) -> SearchPage<Customer> {
                path "search";
                query { query; page; limit; "expand[]" = expand; }
                paginate |call, answer| search_next(&page, call, answer).map_err(concord::mismatch);
            }
        }

        scope payment_intents {
            path "v1/payment_intents";

            POST create(new: NewPaymentIntent, key: IdempotencyKey, expand?: Vec<String>) -> PaymentIntent {
                headers { "Idempotency-Key" = key; }
                body stripe_form(new, expand);
                idempotent;
            }
            GET get(id: PaymentIntentId, expand?: Vec<String>) -> PaymentIntent {
                path "{id}";
                query { "expand[]" = expand; }
            }
            POST update(id: PaymentIntentId, changes: UpdatePaymentIntent, key: IdempotencyKey, expand?: Vec<String>) -> PaymentIntent {
                path "{id}";
                headers { "Idempotency-Key" = key; }
                body stripe_form(changes, expand);
                idempotent;
            }
            /// Success can still require customer action; inspect status/next_action.
            POST confirm(id: PaymentIntentId, options: ConfirmPaymentIntent, key: IdempotencyKey, expand?: Vec<String>) -> PaymentIntent {
                path "{id}/confirm";
                headers { "Idempotency-Key" = key; }
                body stripe_form(options, expand);
                idempotent;
            }
            POST capture(id: PaymentIntentId, options: CapturePaymentIntent, key: IdempotencyKey, expand?: Vec<String>) -> PaymentIntent {
                path "{id}/capture";
                headers { "Idempotency-Key" = key; }
                body stripe_form(options, expand);
                idempotent;
            }
            POST cancel(id: PaymentIntentId, options: CancelPaymentIntent, key: IdempotencyKey, expand?: Vec<String>) -> PaymentIntent {
                path "{id}/cancel";
                headers { "Idempotency-Key" = key; }
                body stripe_form(options, expand);
                idempotent;
            }
            GET list(customer?: CustomerId, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: PaymentIntentId, expand?: Vec<String>) -> List<PaymentIntent> {
                query { customer; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
            /// Search uses page tokens, not PaymentIntent IDs.
            GET search(query: String, page?: String, limit?: u32, expand?: Vec<String>) -> SearchPage<PaymentIntent> {
                path "search";
                query { query; page; limit; "expand[]" = expand; }
                paginate |call, answer| search_next(&page, call, answer).map_err(concord::mismatch);
            }
        }

        scope refunds {
            path "v1/refunds";

            POST create(new: NewRefund, key: IdempotencyKey, expand?: Vec<String>) -> Refund {
                headers { "Idempotency-Key" = key; }
                body stripe_form(new, expand);
                idempotent;
            }
            GET get(id: RefundId, expand?: Vec<String>) -> Refund {
                path "{id}";
                query { "expand[]" = expand; }
            }
            POST update(id: RefundId, changes: UpdateRefund, key: IdempotencyKey, expand?: Vec<String>) -> Refund {
                path "{id}";
                headers { "Idempotency-Key" = key; }
                body stripe_form(changes, expand);
                idempotent;
            }
            /// Stripe permits this only for refunds in requires_action.
            POST cancel(id: RefundId, key: IdempotencyKey) -> Refund {
                path "{id}/cancel";
                headers { "Idempotency-Key" = key; }
                idempotent;
            }
            GET list(charge?: ChargeId, payment_intent?: PaymentIntentId, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: RefundId, expand?: Vec<String>) -> List<Refund> {
                query { charge; payment_intent; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
        }

        scope subscriptions {
            path "v1/subscriptions";

            POST create(new: NewSubscription, key: IdempotencyKey, expand?: Vec<String>) -> Subscription {
                headers { "Idempotency-Key" = key; }
                body stripe_form(new, expand);
                idempotent;
            }
            GET get(id: SubscriptionId, expand?: Vec<String>) -> Subscription {
                path "{id}";
                query { "expand[]" = expand; }
            }
            POST update(id: SubscriptionId, changes: UpdateSubscription, key: IdempotencyKey, expand?: Vec<String>) -> Subscription {
                path "{id}";
                headers { "Idempotency-Key" = key; }
                body stripe_form(changes, expand);
                idempotent;
            }
            /// Cancels now. Use update(cancel_at_period_end) to schedule cancellation.
            DELETE cancel(id: SubscriptionId, invoice_now?: bool, prorate?: bool, expand?: Vec<String>) -> Subscription {
                path "{id}";
                query { invoice_now; prorate; "expand[]" = expand; }
            }
            /// None leaves Stripe's default; All and Ended are filter-only values.
            GET list(customer?: CustomerId, status?: SubscriptionStatusFilter, price?: PriceId, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: SubscriptionId, expand?: Vec<String>) -> List<Subscription> {
                query { customer; status; price; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
        }

        scope invoices {
            path "v1/invoices";

            POST create(new: NewInvoice, key: IdempotencyKey, expand?: Vec<String>) -> Invoice {
                headers { "Idempotency-Key" = key; }
                body stripe_form(new, expand);
                idempotent;
            }
            GET get(id: InvoiceId, expand?: Vec<String>) -> Invoice {
                path "{id}";
                query { "expand[]" = expand; }
            }
            POST update(id: InvoiceId, changes: UpdateInvoice, key: IdempotencyKey, expand?: Vec<String>) -> Invoice {
                path "{id}";
                headers { "Idempotency-Key" = key; }
                body stripe_form(changes, expand);
                idempotent;
            }
            /// Only a deletable one-off draft; finalized invoices must be voided.
            DELETE delete(id: InvoiceId) -> Deleted<InvoiceId> { path "{id}"; }
            GET list(customer?: CustomerId, subscription?: SubscriptionId, status?: InvoiceStatusFilter, collection_method?: CollectionMethod, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: InvoiceId, expand?: Vec<String>) -> List<Invoice> {
                query { customer; subscription; status; collection_method; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
            POST finalize(id: InvoiceId, options: FinalizeInvoice, key: IdempotencyKey, expand?: Vec<String>) -> Invoice {
                path "{id}/finalize";
                headers { "Idempotency-Key" = key; }
                body stripe_form(options, expand);
                idempotent;
            }
            POST pay(id: InvoiceId, options: PayInvoice, key: IdempotencyKey, expand?: Vec<String>) -> Invoice {
                path "{id}/pay";
                headers { "Idempotency-Key" = key; }
                body stripe_form(options, expand);
                idempotent;
            }
            POST void(id: InvoiceId, key: IdempotencyKey) -> Invoice {
                path "{id}/void";
                headers { "Idempotency-Key" = key; }
                idempotent;
            }
            POST mark_uncollectible(id: InvoiceId, key: IdempotencyKey) -> Invoice {
                path "{id}/mark_uncollectible";
                headers { "Idempotency-Key" = key; }
                idempotent;
            }
            POST send_invoice(id: InvoiceId, key: IdempotencyKey) -> Invoice {
                path "{id}/send";
                headers { "Idempotency-Key" = key; }
                idempotent;
            }
        }

        GET balance() -> Balance { path "v1/balance"; }

        scope balance_transactions {
            path "v1/balance_transactions";

            GET get(id: BalanceTransactionId, expand?: Vec<String>) -> BalanceTransaction {
                path "{id}";
                query { "expand[]" = expand; }
            }
            GET list(currency?: Currency, source?: String, transaction_type?: String, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: BalanceTransactionId, expand?: Vec<String>) -> List<BalanceTransaction> {
                query { currency; source; "type" = transaction_type; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; "expand[]" = expand; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
        }

        scope events {
            path "v1/events";

            /// data.object retains its creation-time API version.
            GET get(id: EventId) -> Event { path "{id}"; }
            /// Stripe retains events for retrieval for up to 30 days.
            GET list(event_types?: Vec<String>, delivery_success?: bool, created_from?: i64, created_before?: i64, limit?: u32, starting_after?: EventId) -> List<Event> {
                query { "types[]" = event_types; delivery_success; "created[gte]" = created_from; "created[lt]" = created_before; limit; starting_after; }
                paginate |call, answer| list_next(&starting_after, call, answer).map_err(concord::mismatch);
            }
        }

        scope files {
            base "https://files.stripe.com";
            path "v1/files";

            /// Buffered multipart upload; this helper accepts at most 8 MiB.
            POST upload(purpose: FilePurpose, file: Upload, key: IdempotencyKey) -> StripeFile {
                headers { "Idempotency-Key" = key; }
                body stripe_multipart(purpose, file);
                idempotent;
            }
        }
    }
}

concord::api! {
    /// The GitHub REST API on github.com, version `2022-11-28`: repositories, issues,
    /// pull requests, contents, releases, search, the rate limit.
    ///
    /// GitHub refuses a request with no `User-Agent`, so `new` asks for your program's name.
    /// With no token GitHub allows 60 requests an hour, with one 5 000.
    /// For a program that runs for long, build the client with [`Github::watched`] (it keeps
    /// the quotas) and `.with_retry(retry())` (GitHub's own "later").
    pub client Github(
        /// Sent as `User-Agent` on every request: `"my-tool/1.0"`.
        user_agent: String,
        /// A personal access token, or an app's installation token. Sent as a bearer.
        token?: Secret,
    ) {
        base "https://api.github.com";
        headers {
            "accept" = "application/vnd.github+json";
            "x-github-api-version" = "2022-11-28";
            "user-agent" = user_agent;
            "authorization" = "Bearer {token}";
        }
        read Json;
        problem GitHubProblem;

        /// The quotas of the token (or of your address, with no token). It spends none.
        GET rate_limit() -> RateLimits { path "rate_limit"; }

        /// A repository by its id. This is where the `301` of a renamed repository points
        /// (see [`Github::find_repo`]). (unsure: GitHub's reference does not list it)
        GET repository(id: u64) -> Repository { path "repositories/{id}"; }

        /// The user that the token belongs to.
        scope user {
            path "user";

            GET get() -> User;

            /// Repositories that the user can reach. GitHub refuses `kind` together with
            /// `visibility` (`422`).
            GET repos(
                visibility?: Visibility,
                /// Sent as `type`. `all`, `owner`, `public`, `private`, `member`.
                kind?: RepoType,
                sort?: RepoSort,
                direction?: Direction,
                /// At most 100.
                per_page?: u8,
                page?: u32,
            ) -> Vec<Repository> {
                path "repos";
                query { visibility; "type" = kind; sort; direction; per_page; page; }
                paginate link();
            }

            /// A new repository, owned by the user.
            POST create_repo(repo: NewRepo) -> Repository {
                path "repos";
                body json(repo);
            }
        }

        /// Another user, by login.
        scope users(username: String) {
            path "users/{username}";

            GET get() -> User;

            /// The user's public repositories. `kind` is sent as `type`: `all`, `owner`, `member`.
            GET repos(kind?: RepoType, sort?: RepoSort, direction?: Direction,
                      per_page?: u8, page?: u32) -> Vec<Repository> {
                path "repos";
                query { "type" = kind; sort; direction; per_page; page; }
                paginate link();
            }
        }

        /// An organisation, by login.
        scope orgs(org: String) {
            path "orgs/{org}";

            /// The organisation's repositories that the token may see. `kind` is sent as
            /// `type`: `all`, `public`, `private`, `forks`, `sources`, `member`.
            GET repos(kind?: RepoType, sort?: RepoSort, direction?: Direction,
                      per_page?: u8, page?: u32) -> Vec<Repository> {
                path "repos";
                query { "type" = kind; sort; direction; per_page; page; }
                paginate link();
            }

            /// A new repository in the organisation.
            POST create_repo(repo: NewRepo) -> Repository {
                path "repos";
                body json(repo);
            }
        }

        /// One repository. A `404` here means "no such repository" or "not one the token may
        /// see": GitHub does not say which. Under an old name, every endpoint below answers
        /// `301`: the error's `problem().moved_to()` has the new id (see [`Github::find_repo`]).
        scope repo(owner: String, name: String) {
            path "repos/{owner}/{name}";

            GET get() -> Repository;

            /// The repository, or `None` when it has not changed since `etag` (the `etag` of an
            /// earlier answer). A `304` spends no quota (unsure: only with a token).
            GET get_if_changed(etag?: String) -> Option<Tagged<Repository>> {
                headers { "if-none-match" = etag; }
                status {
                    304 => None,
                    200 { body, headers } => Some(Tagged::new(headers.get("etag"), body)),
                }
            }

            /// Commits, additions and deletions of each contributor, week by week. GitHub
            /// computes them on the first ask and answers `202` meanwhile: `Stats::Computing`.
            /// [`github::Repo::contributor_stats_ready`] asks again for you.
            GET contributor_stats() -> Stats<Vec<ContributorStats>> {
                path "stats/contributors";
                status {
                    200 { body } => Stats::Ready(body),
                    202 => Stats::Computing,
                    204 => Stats::Ready(Vec::new()),      // an empty repository (unsure)
                }
            }

            /// The entries at the root of the repository. (`contents` takes a path, and an
            /// empty path cannot be sent.)
            GET contents_root(
                /// A branch, a tag or a commit. The default branch when not given.
                reference?: String,
            ) -> Vec<Entry> {
                path "contents";
                query { "ref" = reference; }
            }

            /// The issues of the repository, and its issue comments.
            scope issues {
                path "issues";

                /// Issues, newest first. GitHub counts a pull request as an issue: those come
                /// too, with `pull_request` set.
                GET list(
                    /// A milestone number, `Filter::Any` or `Filter::Without`.
                    milestone?: Filter<u64>,
                    /// GitHub gives `open` when this is not sent.
                    state?: StateFilter,
                    /// A login, `Filter::Any` or `Filter::Without`.
                    assignee?: Filter<String>,
                    /// The login of who opened it.
                    creator?: String,
                    /// A login that is mentioned in it.
                    mentioned?: String,
                    /// Issues that have every one of these labels.
                    labels?: Vec<String>,
                    /// Issues updated at or after this time.
                    since?: DateTime<Utc>,
                    sort?: IssueSort,
                    direction?: Direction,
                    per_page?: u8,
                    page?: u32,
                ) -> Vec<Issue> {
                    query {
                        milestone; state; assignee; creator; mentioned;
                        "labels" = labels.as_ref().map(|l| l.join(","));
                        since; sort; direction; per_page; page;
                    }
                    paginate link();
                }

                /// A new issue. Labels, assignees and a milestone need push access; without it
                /// GitHub leaves them out and still creates the issue (unsure).
                POST create(title: String, body?: String, labels?: Vec<String>,
                            assignees?: Vec<String>, milestone?: u64) -> Issue {
                    body compact(json!({
                        "title": title, "body": body, "labels": labels,
                        "assignees": assignees, "milestone": milestone
                    }));
                }

                /// One comment, by its id (the ids run across the whole repository).
                scope comment(id: u64) {
                    path "comments/{id}";

                    GET get() -> Comment;

                    PATCH update(body: String) -> Comment {
                        body json(json!({ "body": body }));
                        idempotent;                    // the text is set, not added to
                    }

                    DELETE delete();
                }
            }

            /// One issue (or pull request), by its number.
            scope issue(number: u64) {
                path "issues/{number}";

                GET get() -> Issue;

                /// Sets the fields that `changes` holds; the others stay as they are.
                PATCH update(changes: IssueUpdate) -> Issue {
                    body json(changes);
                    idempotent;                        // every field is set, none is added to
                }

                GET comments(
                    /// Comments updated at or after this time.
                    since?: DateTime<Utc>,
                    per_page?: u8,
                    page?: u32,
                ) -> Vec<Comment> {
                    path "comments";
                    query { since; per_page; page; }
                    paginate link();
                }

                POST create_comment(body: String) -> Comment {
                    path "comments";
                    body json(json!({ "body": body }));
                }
            }

            /// The pull requests of the repository.
            scope pulls {
                path "pulls";

                /// `head` is `user:branch`; `base` is the branch that they want to merge into.
                GET list(state?: StateFilter, head?: String, base?: String,
                         sort?: PullSort, direction?: Direction,
                         per_page?: u8, page?: u32) -> Vec<PullRequest> {
                    query { state; head; base; sort; direction; per_page; page; }
                    paginate link();
                }

                /// A new pull request: `head` into `base`.
                POST create(title: String, head: String, base: String,
                            body?: String, draft?: bool) -> PullRequest {
                    body compact(json!({
                        "title": title, "head": head, "base": base, "body": body, "draft": draft
                    }));
                }
            }

            /// One pull request, by its number.
            scope pull(number: u64) {
                path "pulls/{number}";

                GET get() -> PullRequest;

                /// The diff as GitHub writes it. Bytes, not text: a changed file that is not
                /// UTF-8 is in the diff as it is.
                GET diff() -> Bytes {
                    headers { override "accept" = "application/vnd.github.diff"; }
                    read Binary;
                }

                /// The changed files, at most 3 000.
                GET files(per_page?: u8, page?: u32) -> Vec<DiffEntry> {
                    path "files";
                    query { per_page; page; }
                    paginate link();
                }

                /// `false` also when there is no such pull request: GitHub answers `404` to both.
                GET is_merged() -> bool {
                    path "merge";
                    status { 2xx => true, 404 => false }
                }

                /// Merge it. With `sha`, only if the head is still that commit.
                PUT merge(commit_title?: String, commit_message?: String,
                          sha?: String, merge_method?: MergeMethod)
                    -> Result<Merged, MergeRefused> {
                    path "merge";
                    body compact(json!({
                        "commit_title": commit_title, "commit_message": commit_message,
                        "sha": sha, "merge_method": merge_method
                    }));
                    idempotent false;      // sent again after a merge that happened, it answers 405
                    status {
                        200 { body } => Ok(body),
                        405 { body } => Err(MergeRefused::NotMergeable(body)),
                        409 { body } => Err(MergeRefused::HeadMoved(body)),
                    }
                }
            }

            /// A file or a directory, by its path in the repository (`src/lib.rs`).
            scope contents(path: String) {
                path "contents/{*path}";

                /// The file (its bytes in base64) or the entries of a directory.
                /// `None`: no such path on that reference.
                GET get(
                    /// A branch, a tag or a commit. The default branch when not given.
                    reference?: String,
                ) -> Option<Contents> {
                    query { "ref" = reference; }
                    status { 404 => None }
                }

                /// The bytes of the file, as they are. Up to 100 MB, GitHub's limit for this
                /// form (unsure); past 1 MB the JSON form above has no content.
                GET raw(reference?: String) -> Bytes {
                    query { "ref" = reference; }
                    headers { override "accept" = "application/vnd.github.raw+json"; }
                    read Binary.limit(100 * concord::MIB);
                }

                /// Create the file, or replace it. Replacing needs `sha`, the blob that it
                /// replaces: when someone wrote first, GitHub answers `409`.
                PUT create_or_update(
                    message: String,
                    /// The new bytes. Sent in base64, as GitHub wants.
                    content: Vec<u8>,
                    sha?: String,
                    /// The default branch when not given.
                    branch?: String,
                ) -> FileCommit {
                    body compact(json!({
                        "message": message, "content": STANDARD.encode(content),
                        "sha": sha, "branch": branch
                    }));
                    idempotent false;      // sent again after a write that happened: 409 or 422
                }
            }

            /// The releases of the repository.
            scope releases {
                path "releases";

                /// Published releases, and drafts for a token with push access.
                GET list(per_page?: u8, page?: u32) -> Vec<Release> {
                    query { per_page; page; }
                    paginate link();
                }

                POST create(release: NewRelease) -> Release { body json(release); }

                /// The latest published release that is not a pre-release.
                GET latest() -> Release { path "latest"; }

                /// A tag may hold `/` (`release/1.0`). (unsure: that GitHub reads it unencoded)
                GET by_tag(tag: String) -> Release { path "tags/{*tag}"; }
            }

            /// One release, by its id.
            scope release(id: u64) {
                path "releases/{id}";

                GET get() -> Release;

                DELETE delete();

                GET assets(per_page?: u8, page?: u32) -> Vec<Asset> {
                    path "assets";
                    query { per_page; page; }
                    paginate link();
                }

                /// GitHub's upload host.
                scope upload {
                    base "https://uploads.github.com";

                    /// Attach a file to the release. `file` carries its media type
                    /// (`Body::new(bytes, "application/zip")`) and needs a known length (unsure).
                    /// The time to send it counts as silence: give a large file
                    /// `.with_idle_timeout(…)`. A name that is taken: `422`.
                    POST asset(name: String, label?: String, file: concord::Body) -> Asset {
                        path "assets";
                        query { name; label; }
                        body file;
                    }
                }
            }
        }

        /// Search. It has its own quota: 30 requests a minute with a token.
        scope search {
            path "search";

            /// Repositories that match `q`, in GitHub's search syntax
            /// (`"language:rust stars:>1000"`). At most 1 000 results in all.
            GET repositories(q: String, sort?: RepoSearchSort, order?: Direction,
                             per_page?: u8, page?: u32) -> SearchResults<Repository> {
                path "repositories";
                query { q; sort; order; per_page; page; }
                paginate link();
            }

            /// Issues and pull requests that match `q` (`"repo:rust-lang/rust is:open label:C-bug"`).
            GET issues(q: String, sort?: IssueSearchSort, order?: Direction,
                       per_page?: u8, page?: u32) -> SearchResults<Issue> {
                path "issues";
                query { q; sort; order; per_page; page; }
                paginate link();
            }
        }
    }
}

concord::api! {
    /// An object store that speaks the S3 protocol: Amazon S3, or a store that copies it
    /// (MinIO, Ceph, Cloudflare R2, …).
    ///
    /// **Every request must be signed** (Signature Version 4). Make the client with
    /// [`S3::signed`] for AWS, or [`S3::compatible`] for another store. `S3::new` compiles,
    /// and gives a client that does not sign: S3 answers it `403`.
    pub client S3(
        /// The region, as AWS writes it: `eu-west-1`.
        region: Region,
    ) {
        base "https://s3.{region}.amazonaws.com";
        read Xml;
        problem S3Problem;

        /// How the object is stored and served back: on `put`, `copy_from`, `create_multipart_upload`.
        part object_headers(content_type?: String, cache_control?: String,
                            content_disposition?: String, content_encoding?: String,
                            storage_class?: StorageClass) {
            headers {
                "content-type" = content_type;
                "cache-control" = cache_control;
                "content-disposition" = content_disposition;
                "content-encoding" = content_encoding;
                "x-amz-storage-class" = storage_class;
            }
        }

        /// ListBuckets: the buckets of the account. In pages since 2024 (unsure); a store
        /// that does not page sends one page with no token.
        GET list_buckets(prefix?: String, bucket_region?: Region,
                         max_buckets?: u32, continuation_token?: String) -> BucketList {
            query { prefix; "bucket-region" = bucket_region; "max-buckets" = max_buckets;
                    "continuation-token" = continuation_token; }
            paginate cursor(continuation_token, BucketList::next_token);
        }

        /// One bucket. Written in the path here; on AWS the signer puts it in the host
        /// (`{name}.s3.{region}.amazonaws.com`), unless the name has a dot. See [`Addressing`].
        scope bucket(name: String) {
            path "{name}";

            /// HeadBucket. `None` when there is no such bucket. One that exists and is not
            /// yours is a `403`, an error.
            HEAD head() -> Option<BucketHead> {
                status {
                    2xx { headers } => Some(BucketHead::from_headers(headers)),
                    301 { headers } => Some(BucketHead::from_headers(headers)),   // it lives in another region (unsure)
                    404 => None,
                }
            }

            /// CreateBucket, in the region of this client.
            PUT create(object_ownership?: ObjectOwnership) {
                headers { "x-amz-object-ownership" = object_ownership; }
                body bucket_configuration(client.region);
            }

            /// DeleteBucket. The bucket must be empty.
            DELETE delete();

            /// ListObjectsV2: the objects in the order of their keys, a page at a time. With a
            /// `delimiter`, the keys that share a prefix up to it come once, in `common_prefixes`.
            GET list_objects(prefix?: String, delimiter?: String, max_keys?: u16,
                             start_after?: String, fetch_owner?: bool,
                             continuation_token?: String) -> ListBucketResult {
                query { "list-type" = "2"; prefix; delimiter; "max-keys" = max_keys; "start-after" = start_after;
                        "fetch-owner" = fetch_owner; "continuation-token" = continuation_token; }
                paginate |call, page| match (page.value().is_truncated, &page.value().next_continuation_token) {
                    (true, Some(token)) => Ok(Some(call.continuation_token(token.clone()))),
                    (true, None) => Err(concord::mismatch("IsTruncated without a NextContinuationToken")),
                    (false, _) => Ok(None),
                };
            }

            /// DeleteObjects: up to 1000 keys in one request. A key that could not be deleted is
            /// in `errors`, and the call itself succeeds.
            POST delete_objects(keys: Vec<String>, quiet?: bool) -> DeleteResult {
                query { "delete" = ""; }
                headers { "content-md5" = DeleteRequest::new(keys, *quiet).content_md5(); }
                body xml(&DeleteRequest::new(keys, *quiet));
                idempotent;
            }

            /// ListMultipartUploads: uploads that were started and neither completed nor aborted.
            GET list_multipart_uploads(prefix?: String, max_uploads?: u16,
                                       key_marker?: String,
                                       upload_id_marker?: UploadId) -> ListMultipartUploadsResult {
                query { "uploads" = ""; prefix; "max-uploads" = max_uploads;
                        "key-marker" = key_marker; "upload-id-marker" = upload_id_marker; }
                paginate |call, page| page.value().next_markers()
                    .map(|(key, id)| call.key_marker(key).upload_id_marker(id));
            }

            /// One object. Its key may hold `/`: `photos/2026/cat.jpg`. A key that ends with
            /// `/`, or holds `//`, cannot be sent (finding 3).
            scope object(key: String) {
                path "{*key}";

                /// GetObject: the head, and the bytes as they come. With `range`, a part of them
                /// (`206`). `idle_timeout` goes on while you read.
                GET get(range?: ByteRange, if_match?: ETag, version_id?: VersionId) -> Download {
                    query { "versionId" = version_id; }
                    headers { range; "if-match" = if_match; }
                    read Stream;
                    status { 2xx { body, headers } => Download::new(body, headers)? }
                }

                /// GetObject with `If-None-Match`: `None` while the object still has this ETag (`304`).
                GET get_if_changed(etag: ETag, range?: ByteRange) -> Option<Download> {
                    headers { "if-none-match" = etag; range; }
                    read Stream;
                    status {
                        2xx { body, headers } => Some(Download::new(body, headers)?),
                        304 => None,
                    }
                }

                /// HeadObject: the head that `get` gives, with no bytes. `None` when there is no
                /// such key. (A caller without `s3:ListBucket` gets `403` instead: S3 hides which.)
                HEAD head(version_id?: VersionId) -> Option<ObjectHead> {
                    query { "versionId" = version_id; }
                    status {
                        2xx { headers } => Some(ObjectHead::from_headers(headers)?),
                        404 => None,
                    }
                }

                /// PutObject: up to 5 GiB in one request. A stream is sent once, and needs
                /// `content_length`: S3 refuses a chunked body. `.if_none_match("*")` writes only
                /// if there is no object at this key (`412` otherwise). User metadata: `.meta(…)`.
                PUT put(content: Body, content_length?: u64, if_none_match?: String,
                        ..object_headers) -> Stored {
                    headers { "content-length" = content_length; "if-none-match" = if_none_match; }
                    body content;
                    status {
                        2xx { headers } => Stored {
                            etag: ETag::new(headers.require("etag")?),
                            version_id: headers.get("x-amz-version-id").map(VersionId::new),
                        },
                    }
                }

                /// CopyObject: this object, made on the server from `source` (5 GiB at most).
                /// A `200` can still carry an error; it is read, and is an error here too.
                PUT copy_from(source: CopySource, metadata_directive?: MetadataDirective,
                              source_if_match?: ETag, ..object_headers) -> CopyObjectResult {
                    headers {
                        "x-amz-copy-source" = source;
                        "x-amz-metadata-directive" = metadata_directive;
                        "x-amz-copy-source-if-match" = source_if_match;
                    }
                    status { 200 { body: reply } => XmlReply::into_result(reply)? }
                }

                /// DeleteObject. A key that is not there is "deleted" too: `204` either way.
                DELETE delete(version_id?: VersionId) {
                    query { "versionId" = version_id; }
                }

                /// CreateMultipartUpload. Each call starts a new upload, kept (and billed) until it
                /// is completed or aborted; so it is never sent twice.
                POST create_multipart_upload(..object_headers) -> InitiateMultipartUploadResult {
                    query { "uploads" = ""; }
                }

                /// One multipart upload of this object.
                scope multipart(upload_id: UploadId) {
                    query { "uploadId" = upload_id; }

                    /// UploadPart: part `part_number` (1 to 10 000; 5 MiB at least, but the last).
                    /// Bytes held in memory can be sent again; a stream is sent once.
                    PUT upload_part(part_number: u16, part: Body, content_length?: u64) -> CompletedPart {
                        query { "partNumber" = part_number; }
                        headers { "content-length" = content_length; }
                        body part;
                        status { 2xx { headers } => CompletedPart { part_number: *part_number, etag: ETag::new(headers.require("etag")?) } }
                    }

                    /// CompleteMultipartUpload: the object, made of these parts in this order. It
                    /// can take minutes (S3 sends spaces meanwhile), and a `200` can carry an error.
                    POST complete(parts: Vec<CompletedPart>) -> CompleteMultipartUploadResult {
                        body xml(&CompleteMultipartUpload { parts });
                        status { 200 { body: reply } => XmlReply::into_result(reply)? }
                        idempotent;     // the same parts make the same object (unsure: a repeat after success may say NoSuchUpload)
                    }

                    /// AbortMultipartUpload: the parts are dropped, and no longer billed.
                    DELETE abort();

                    /// ListParts: the parts uploaded so far.
                    GET list_parts(max_parts?: u16, part_number_marker?: u16) -> ListPartsResult {
                        query { "max-parts" = max_parts; "part-number-marker" = part_number_marker; }
                        paginate cursor(part_number_marker, ListPartsResult::next_marker);
                    }
                }
            }
        }
    }
}
